sealed interface Intent {
    record Refresh() implements Intent {}
    record Loaded(List<Item> items) implements Intent {}
    record Failed(String message) implements Intent {}
}
record UiState(List<Item> items, boolean loading, String error) {}

static UiState reduce(UiState s, Intent i) {
    return switch (i) {
        case Intent.Refresh r -> new UiState(s.items(), true, null);
        case Intent.Loaded l  -> new UiState(List.copyOf(l.items()), false, null);
        case Intent.Failed f  -> new UiState(s.items(), false, f.message());
    };
}
